  function getTaskInfo(){
    var cur = null;
    for(var i=0; i<DAILY_TASKS.length; i++){
      if(DAILY_TASKS[i].id === state.taskId){ cur = DAILY_TASKS[i]; break; }
    }
    if(!cur) cur = DAILY_TASKS[0];
    var customName = state.taskCustomName && state.taskCustomName.trim();
    return {
      id: cur.id,
      icon: cur.icon,
      name: (cur.id === 'custom' && customName) ? customName : (state.lang === 'zh' ? (cur.name_zh || cur.name_en) : (state.lang === 'es' ? cur.name_es : cur.name_en)),
      defaultMin: cur.defaultMin
    };
  }

  function flatPool(mode){
    var m = (mode === 'task' || !IMAGE_LIBRARY[mode]) ? 'leaving' : mode;
    return IMAGE_LIBRARY[m].reduce(function(acc, cat){ return acc.concat(cat.items); }, []);
  }

