  function getCopy(mode, lang){
    var m = mode || 'leaving';
    var l = lang || 'en';
    if(COPY[m] && COPY[m][l]) return COPY[m][l];
    if(COPY[m] && COPY[m]['en']) return COPY[m]['en'];
    if(COPY['leaving'] && COPY['leaving'][l]) return COPY['leaving'][l];
    return COPY['leaving']['en'];
  }

