  function confettiBurst(){
    var layer = document.getElementById('confettiLayer');
    var isBedtime = state.mode === 'bedtime';
    if(isBedtime){
      var zzz = document.createElement('div');
      zzz.className = 'sleepZzz';
      zzz.textContent = 'ZZZZZZ';
      layer.appendChild(zzz);
      setTimeout(function(){ zzz.remove(); }, 5200);

      // Spread the bears across the screen so they fall in a gentle horizontal row.
      var bears = [12, 29, 46, 63, 80];
      bears.forEach(function(position, index){
        var bear = document.createElement('div');
        bear.className = 'sleepBear';
        bear.textContent = '🧸';
        bear.style.left = (position + (Math.random()*6 - 3)) + 'vw';
        bear.style.animationDuration = (4.2 + Math.random()*1.8) + 's';
        bear.style.animationDelay = (index * 0.18) + 's';
        bear.style.fontSize = (40 + Math.random()*18) + 'px';
        layer.appendChild(bear);
        (function(node){ setTimeout(function(){ node.remove(); }, 7000); })(bear);
      });
      return;
    }

    var bits = ["⭐","🎉","✨","🌟","🎊"];
    for(var i=0;i<18;i++){
      var el = document.createElement('div');
      el.className = 'confetti';
      el.textContent = bits[Math.floor(Math.random()*bits.length)];
      el.style.left = Math.random()*100 + "vw";
      el.style.animationDuration = (2 + Math.random()*1.5) + "s";
      el.style.fontSize = (14 + Math.random()*14) + "px";
      layer.appendChild(el);
      (function(node){ setTimeout(function(){ node.remove(); }, 3800); })(el);
    }
  }

  function beep(freq, dur){
    try{
      var ctx = beep._ctx || (beep._ctx = new (window.AudioContext||window.webkitAudioContext)());
      if(ctx.state === 'suspended') ctx.resume();
      var o = ctx.createOscillator();
      var g = ctx.createGain();
      o.type = 'sine';
      o.frequency.value = freq;
      g.gain.setValueAtTime(0.001, ctx.currentTime);
      g.gain.linearRampToValueAtTime(0.06, ctx.currentTime + 0.02);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + dur);
      o.connect(g); g.connect(ctx.destination);
      o.start();
      o.stop(ctx.currentTime + dur + 0.02);
    }catch(e){}
  }

