  async function checkLicenseKey(key){
    try{
      var res = await fetch('https://api.lemonsqueezy.com/v1/licenses/validate', {
        method:'POST',
        headers:{'Accept':'application/json','Content-Type':'application/x-www-form-urlencoded'},
        body:'license_key=' + encodeURIComponent(key)
      });
      var data = await res.json();
      if(data && data.valid && data.meta && String(data.meta.product_id) === String(LEMON_SQUEEZY_PRODUCT_ID)){
        return true;
      }
      return false;
    }catch(e){
      return false;
    }
  }

