  function themedTimerHTML(themeId, progress){
    var theme = null;
    for(var i=0;i<TIMER_THEMES.length;i++){ if(TIMER_THEMES[i].id===themeId){ theme = TIMER_THEMES[i]; break; } }
    if(!theme) theme = TIMER_THEMES[0];
    var stageIdx = Math.min(3, Math.floor(progress*4));
    return '<img class="timerThemeImg" src="'+theme.images[stageIdx]+'" alt="" />';
  }

  function plainClockHTML(progress){
    var deg = Math.min(360, Math.max(0, progress * 360));
    var radius = 82;
    var circumference = 2 * Math.PI * radius;
    var offset = circumference * (1 - Math.min(1, Math.max(0, progress)));
    return ''+
    '<div class="clockFace">'+
      '<div class="clockTick tick-12"></div>'+
      '<div class="clockTick tick-3"></div>'+
      '<div class="clockTick tick-6"></div>'+
      '<div class="clockTick tick-9"></div>'+
      '<svg width="208" height="208" viewBox="0 0 200 200" style="position:absolute;top:0;left:0;">'+
        '<circle cx="100" cy="100" r="82" fill="none" stroke="rgba(255,255,255,0.08)" stroke-width="14" />'+
        '<circle cx="100" cy="100" r="82" fill="none" stroke="var(--coral)" stroke-width="14" '+
          'stroke-dasharray="'+circumference.toFixed(2)+'" stroke-dashoffset="'+offset.toFixed(2)+'" '+
          'stroke-linecap="round" transform="rotate(-90 100 100)" style="transition:stroke-dashoffset .2s linear;" />'+
        '<line x1="100" y1="100" x2="100" y2="38" stroke="var(--sand)" stroke-width="4" stroke-linecap="round" '+
          'transform="rotate('+deg.toFixed(1)+' 100 100)" />'+
      '</svg>'+
      '<div class="clockCenter"></div>'+
    '</div>';
  }

  function plainHourglassHTML(progress){
    var p = Math.min(1, Math.max(0, progress));
    var topH = (1 - p) * 44;
    var botH = p * 44;
    return ''+
    '<div style="width:220px;height:220px;display:flex;align-items:center;justify-content:center;">'+
      '<svg class="hourglassSvg" width="170" height="200" viewBox="0 0 170 200">'+
        '<defs>'+
          '<clipPath id="topBulb"><polygon points="32,28 138,28 85,96" /></clipPath>'+
          '<clipPath id="botBulb"><polygon points="85,104 138,172 32,172" /></clipPath>'+
        '</defs>'+
        '<rect x="20" y="16" width="130" height="12" rx="6" fill="var(--sand-dark)" />'+
        '<rect x="20" y="172" width="130" height="12" rx="6" fill="var(--sand-dark)" />'+
        '<path d="M 32 28 Q 85 96 85 100 Q 85 104 32 172 L 138 172 Q 85 104 85 100 Q 85 96 138 28 Z" fill="rgba(255,255,255,0.06)" stroke="rgba(255,255,255,0.3)" stroke-width="4" />'+
        '<g clip-path="url(#topBulb)">'+
          '<rect x="30" y="'+(96 - topH)+'" width="110" height="'+topH+'" fill="var(--coral)" />'+
        '</g>'+
        (p < 1 ? '<line x1="85" y1="96" x2="85" y2="168" stroke="var(--coral)" stroke-width="3" stroke-dasharray="4 2" opacity="0.85" />' : '')+
        '<g clip-path="url(#botBulb)">'+
          '<rect x="30" y="'+(172 - botH)+'" width="110" height="'+botH+'" fill="var(--coral)" />'+
        '</g>'+
      '</svg>'+
    '</div>';
  }

