  function playCelebrationFanfare(ageKey){
    var k = ageKey || (state.activeScratchCard && state.activeScratchCard.item && state.activeScratchCard.item.ageGroup) || state.rewardsAge || state.age || 'mid';
    if (k === 'young') {
      playCountingStarsFanfare();
    } else if (k === 'big') {
      playLootDropFanfare();
    } else {
      beep(523.25, 0.15);
      setTimeout(function(){ beep(659.25, 0.15); }, 150);
      setTimeout(function(){ beep(783.99, 0.18); }, 300);
      setTimeout(function(){ beep(1046.50, 0.35); }, 450);
    }
  }

  var recentCardHistory = [];

  function pickScratchItem(ageKey){
    var list = getCollectiblesForAge(ageKey);
    var collectedIds = (state.collectedStickers || []).map(function(s){ return s.id; });
    var uncollected = list.filter(function(c){ return collectedIds.indexOf(c.id) === -1; });

    // 1. Prioritize uncollected cards first, avoiding any drawn in the last few picks
    if (uncollected.length > 0) {
      var candidateUncollected = uncollected.filter(function(c){ return recentCardHistory.indexOf(c.id) === -1; });
      var pool = candidateUncollected.length > 0 ? candidateUncollected : uncollected;
      var picked = pool[Math.floor(Math.random() * pool.length)];
      recentCardHistory.push(picked.id);
      if (recentCardHistory.length > 8) recentCardHistory.shift();
      return picked;
    }

    // 2. If all cards have been unlocked once, draw from the full deck avoiding the last 8 cards drawn
    var candidatePool = list.filter(function(c){ return recentCardHistory.indexOf(c.id) === -1; });
    if (candidatePool.length === 0) {
      recentCardHistory = [];
      candidatePool = list;
    }
    var chosen = candidatePool[Math.floor(Math.random() * candidatePool.length)];
    recentCardHistory.push(chosen.id);
    if (recentCardHistory.length > 8) recentCardHistory.shift();
    return chosen;
  }

  function saveCollectedSticker(item){
    if (!state.collectedStickers) state.collectedStickers = [];
    var exists = state.collectedStickers.some(function(s){ return s.id === item.id; });
    if (!exists) {
      state.collectedStickers.push({
        id: item.id,
        unlockedAt: new Date().toISOString()
      });
      try {
        if (typeof window !== 'undefined' && window.localStorage) {
          localStorage.setItem('calm_collected_stickers', JSON.stringify(state.collectedStickers));
        }
      } catch(e){}
    }
  }

